'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
let variant=OrionProgress.variant('balance'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,guess=0,solved=false,hintDepth=0,state='ready',history=[],saveFailed=false;
function puzzle(v=variant,s=stage){const value=[2+v,1+(v+2)%8,1+(v+4)%8][s],gems=s===2?2:1,extra=s===1?2+v%3:0;return{value,gems,extra,total:gems*value+extra};}
function resetTrial(){guess=0;solved=false;hintDepth=0;state='ready';history=[];saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('balance')){variant=v;stage=0;resetTrial();}
function setGuess(n){if(solved||!Number.isInteger(n)||n<0||n>9)return;guess=n;state='changed';render();}
function check(){if(solved)return;const p=puzzle();history.unshift(guess);if(p.gems*guess+p.extra!==p.total){state='wrong';render();return;}solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('balance');render();if(stage<2)$('next').focus();}
function hints(){const p=puzzle();return[t('The = sign asks for the same total on both sides. Try changing the value of one gem.','等號 = 要求兩邊總數相同。試着改變一顆寶石的數值。'),p.extra?t(`The left side already has ${p.extra} blocks. Take those away from ${p.total} to find the gem.`,`左邊已有 ${p.extra} 塊方塊。從 ${p.total} 減去它們，就找到寶石的數值。`):p.gems===2?t(`Split ${p.total} equally between the two identical gems.`,`把 ${p.total} 平分給兩顆相同寶石。`):t('One gem must have the same value as all the blocks on the right.','一顆寶石的數值，要跟右邊全部方塊相同。'),t(`Try ${p.value} for each gem, then unlock the seal.`,`每顆寶石試 ${p.value}，再打開封印。`)];}
function render(){const p=puzzle(),left=p.gems*guess+p.extra,diff=left-p.total,complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Gem Balance · Orion','寶石天平室 · Orion');$('stageTitle').textContent=t(`Seal ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道封印 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Seals opened · ${count} / 3`,`已打開 ${count} / 3 道封印`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('progressCount').textContent=$('sceneStatus').textContent;$('progressBar').value=count;$('scene').classList.toggle('complete',complete);$('mission').textContent=t('Find the hidden value of ONE gem. Test a number until both sides are equal.','找出一顆寶石的隱藏數值。試試數字，直到兩邊相等。');$('guessLabel').textContent=t(`Try each gem as ${guess} blocks`,`每顆寶石試作 ${guess} 塊方塊`);$('guess').value=guess;for(const id of ['guess','minus','plus'])$(id).disabled=solved;$('minus').disabled=solved||guess===0;$('plus').disabled=solved||guess===9;
const eq=`${p.gems===2?'◆ + ◆':'◆'}${p.extra?' + '+p.extra:''} = ${p.total}`;$('goal').textContent=t('Solve: ','解開：')+eq;$('reading').textContent=t(`Your test: ${left} ${diff===0?'=':diff>0?'>':'<'} ${p.total}`,`你的測試：${left} ${diff===0?'=':diff>0?'>':'<'} ${p.total}`);
const angle=diff===0?0:diff>0?-9:9,ly=diff===0?0:diff>0?22:-22,ry=-ly;
const blocks=(n,x,y)=>Array.from({length:n},(_,i)=>`<rect x="${x+(i%6)*18}" y="${y-Math.floor(i/6)*18}" width="15" height="15" rx="2" fill="#edc575"/>`).join('');
$('diagram').setAttribute('aria-label',t(`Balance model: left ${left}, right ${p.total}. ${diff===0?'Level.':diff>0?'Left side lower.':'Right side lower.'}`,`天平模型：左邊 ${left}，右邊 ${p.total}。${diff===0?'水平。':diff>0?'左邊較低。':'右邊較低。'}`));$('diagram').innerHTML=`<svg viewBox="0 0 440 250" aria-hidden="true"><path d="M220 60V218M168 224H272" stroke="#c8a35d" stroke-width="12" stroke-linecap="round"/><g class="scale-beam" transform="rotate(${angle} 220 70)"><path d="M80 70H360" stroke="#edc575" stroke-width="9"/></g><g transform="translate(0 ${ly})"><path d="M80 70L30 176H130Z" fill="none" stroke="#9b997a" stroke-width="2"/><path d="M25 176Q80 220 135 176" fill="#aa8045"/><text x="80" y="135" text-anchor="middle" fill="#65dfd0" font-size="30">${'◆'.repeat(p.gems)}</text>${blocks(p.extra,48,154)}<text x="80" y="225" text-anchor="middle" fill="#fff" font-size="19">${left}</text></g><g transform="translate(0 ${ry})"><path d="M360 70L310 176H410Z" fill="none" stroke="#9b997a" stroke-width="2"/><path d="M305 176Q360 220 415 176" fill="#aa8045"/>${blocks(p.total,309,154)}<text x="360" y="225" text-anchor="middle" fill="#fff" font-size="19">${p.total}</text></g></svg>`;
const msg={ready:t('Slide the number to test your first idea.','拖動數字，測試你的第一個想法。'),changed:diff===0?t('Level! Both totals match. Unlock this seal.','水平了！兩邊總數相同。打開封印吧。'):diff>0?t('Your left total is too large. Try a smaller gem value.','左邊總數太大。試試較小的寶石數值。'):t('Your left total is too small. Try a larger gem value.','左邊總數太小。試試較大的寶石數值。'),wrong:t('Not equal yet. Change the gem value and try again.','還未相等。改變寶石數值，再試一次。'),success:t('Equal totals! A treasure seal opens.','總數相等！一道寶藏封印打開了。')};$('feedback').textContent=msg[state];$('log').innerHTML=history.slice(0,4).map(n=>`<li>◆ = ${n} → ${p.gems*n+p.extra} ${p.gems*n+p.extra===p.total?'=':'≠'} ${p.total}</li>`).join('')||`<li>${t('Your checked numbers appear here.','檢查過的數字會記錄在這裡。')}</li>`;for(const id of ['check','retry'])$(id).hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('balance')?t('Balance Sigil saved in your collection.','平衡符印已存入收藏。'):'';
}
$('guess').oninput=e=>setGuess(Number(e.target.value));$('minus').onclick=()=>setGuess(guess-1);$('plus').onclick=()=>setGuess(guess+1);$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('guess').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('balance',variant);observedVariant=OrionProgress.variant('balance');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('balance');render();};
function syncProgress(){const v=OrionProgress.variant('balance'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('balance')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
